#!/usr/bin/env node
// Добавляет отправку почты в проект tg-channel-manager:
//   1) письмо с кодом при восстановлении пароля («Забыли пароль?» на странице входа, страница /forgot);
//   2) письмо новому администратору или редактору в стиле приложения: логин, пароль и описание из руководства пользователя.
// Также: раздел «Письма и восстановление пароля» в руководстве пользователя, переменные SMTP_* в .env.example и docker-compose.prod.yml,
// раздел «Почта» в README, команда проверки  npm run mail:test -- адрес@пример.рф.
// Запуск:  node add-email.mjs [путь/к/проекту]      (по умолчанию — текущая папка)
// После запуска:  npm install  (ставится nodemailer), заполнить SMTP_* в .env, пересобрать и перезапустить приложение.
// Основные файлы меняются по принципу «всё или ничего»: если какой-то из них отличается от ожидаемого, скрипт ничего не трогает
// и пишет, какое именно место не нашёл. Документация, руководство и docker-compose при несовпадении пропускаются с предупреждением.
// Переводы строк (LF/CRLF) сохраняются. Повторный запуск безопасен; копии изменённых файлов — *.bak-mail.
// Схема БД расширяется сама при старте (новая таблица password_resets), удалять и пересоздавать базу не нужно.
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(process.argv[2] || '.');
const dec = (s) => Buffer.from(s, 'base64').toString('utf8');
const p = (f) => path.join(root, f);
const exists = (f) => fs.existsSync(p(f));
const load = (f) => {
  const raw = fs.readFileSync(p(f), 'utf8');
  return { text: raw.replace(/\r\n/g, '\n'), crlf: raw.includes('\r\n') };
};
const save = (f, text, crlf) => fs.writeFileSync(p(f), crlf ? text.replace(/\n/g, '\r\n') : text);

const DATA = JSON.parse(dec(''));

const fail = (title, lines) => {
  console.error(title);
  for (const l of lines) console.error('  - ' + l);
  process.exit(1);
};

// ---- движок правок ----
function applyOp(text, op) {
  if (op.kind === 'replace') {
    return text.split(op.old).length - 1 === 1 ? text.replace(op.old, () => op.text) : null;
  }
  for (const pat of op.pats ?? []) {
    const m = new RegExp(pat.re, pat.flags).exec(text);
    if (!m) continue;
    if (op.kind === 'before' || op.kind === 'after') {
      const ins = op.expand ? op.text.replace(/\$(\d)/g, (_, d) => m[d] ?? '') : op.text;
      const pos = op.kind === 'before' ? m.index : m.index + m[0].length;
      return text.slice(0, pos) + ins + text.slice(pos);
    }
    if (op.kind === 'obj_add') {
      const missing = op.names.filter((n) => !new RegExp('\\b' + n + '\\b').test(m[2]));
      if (!missing.length) return text;
      const trail = m[2].match(/\s*$/)[0];
      const body = m[2].slice(0, m[2].length - trail.length);
      const inner = body + (body.endsWith(',') ? '' : ',') + ' ' + missing.join(', ') + trail;
      return text.slice(0, m.index) + m[1] + inner + m[3] + text.slice(m.index + m[0].length);
    }
  }
  return null;
}
function applyOps(text, ops) {
  const failed = [];
  for (const op of ops) {
    if (op.unless && new RegExp(op.unless).test(text)) continue;
    const next = applyOp(text, op);
    if (next === null) failed.push(op.desc);
    else text = next;
  }
  return { text, failed };
}

// 0. это нужный проект
const need = [];
for (const f of ['server/express/routes/auth.js', 'server/express/routes/users.js', 'server/express/sealed.js', 'composables/useAuth.ts', 'pages/login.vue']) {
  if (!exists(f)) need.push(`${f}: файл не найден (это папка проекта tg-channel-manager?)`);
}
if (need.length) fail('Ничего не изменено:', need);

// 1. проверяем всё заранее, ничего не записывая
const conflicts = [];
const warnings = [];
const plan = { files: [], edits: [], appends: [], fallbacks: [], skipped: [] };

for (const [rel, b64] of Object.entries(DATA.files)) {
  const content = dec(b64);
  if (!exists(rel)) plan.files.push([rel, content]);
  else if (load(rel).text === content) plan.skipped.push(rel);
  else conflicts.push(`${rel}: файл уже есть и отличается от нового (удалите его или перенесите изменения вручную)`);
}
for (const g of DATA.groups) {
  if (!exists(g.rel)) {
    (g.required ? conflicts : warnings).push(`${g.rel}: файл не найден${g.hint ? '. ' + g.hint : ''}`);
    continue;
  }
  const { text, crlf } = load(g.rel);
  if (text.includes(g.marker)) { plan.skipped.push(g.rel); continue; }
  const res = applyOps(text, g.ops);
  if (!res.failed.length) { plan.edits.push([g.rel, res.text, crlf]); continue; }
  if (g.required) {
    for (const d of res.failed) conflicts.push(`${g.rel}: не найдено место для правки «${d}» (файл отличается от версии, на которую рассчитан скрипт)`);
  } else {
    warnings.push(`${g.rel}: пропущен, не найдено место для правки «${res.failed[0]}»${res.failed.length > 1 ? ` и ещё ${res.failed.length - 1}` : ''}. ${g.hint ?? ''}`.trim());
    if (g.fallback) plan.fallbacks.push([g.fallback.file, g.fallback.text]);
  }
}
for (const a of DATA.appends) {
  if (!exists(a.rel)) { warnings.push(`${a.rel}: файл не найден, добавьте переменные SMTP_* вручную`); continue; }
  const { text, crlf } = load(a.rel);
  if (text.includes(dec(a.marker))) plan.skipped.push(a.rel);
  else plan.appends.push([a.rel, (text.endsWith('\n') ? text : text + '\n') + dec(a.text), crlf]);
}
if (conflicts.length) {
  fail('Ничего не изменено. Эти файлы отличаются от версии, на которую рассчитан скрипт:', conflicts);
}

// 2. применяем
const backup = (rel) => {
  const bak = p(rel + '.bak-mail');
  if (!fs.existsSync(bak)) fs.copyFileSync(p(rel), bak);
};
for (const [rel, content] of plan.files) {
  fs.mkdirSync(path.dirname(p(rel)), { recursive: true });
  fs.writeFileSync(p(rel), content);
}
for (const [rel, text, crlf] of [...plan.edits, ...plan.appends]) {
  backup(rel);
  save(rel, text, crlf);
}
for (const [file, text] of plan.fallbacks) fs.writeFileSync(p(file), text);

const changed = plan.files.length + plan.edits.length + plan.appends.length;
if (!changed && !plan.fallbacks.length) {
  console.log('Почта уже добавлена, ничего не изменено.');
  process.exit(0);
}
console.log(`Готово. Создано файлов: ${plan.files.length}, изменено: ${plan.edits.length + plan.appends.length}.`);
for (const [rel] of plan.files) console.log('  + ' + rel);
for (const [rel] of [...plan.edits, ...plan.appends]) console.log('  ~ ' + rel + '   (копия: ' + rel + '.bak-mail)');
if (warnings.length) {
  console.log('\nНе применено (не критично):');
  for (const w of warnings) console.log('  ! ' + w);
}
for (const [file] of plan.fallbacks) console.log(`\nТекст для руководства сохранён в ${file}: вставьте его в pages/guide.vue вручную.`);
console.log(`
Дальше:
  1. npm install                      (добавлен пакет nodemailer; обновится package-lock.json)
  2. Заполните в .env:  SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS, MAIL_FROM  (и при желании APP_URL)
  3. npm run mail:test -- ваш@адрес   (проверка отправки)
  4. npm run build и перезапуск приложения (pm2 restart ecosystem.config.cjs --update-env  /  docker compose -f docker-compose.prod.yml up -d --build)
     Схема БД обновится сама при старте.
  5. Откройте страницу входа в браузере с Ctrl+F5: появится ссылка «Забыли пароль?».
Пока SMTP не заполнен, почта выключена и приложение работает как раньше.`);
